export declare const payeeTypeDefs = "\ntype Payee {\n  id: ID!\n  name: String!\n  accountNumber: String!\n  bankCode: String!\n  accountType: AccountType!\n}\n\nenum AccountType {\n  CHECKING\n  SAVINGS\n}\n\ntype ValidatePayeeResult {\n  isValid: Boolean!\n  matchLevel: MatchLevel!\n  confidence: Float!\n  suggestedName: String\n}\n\nenum MatchLevel {\n  EXACT\n  CLOSE\n  NO_MATCH\n}\n\ninput ValidatePayeeInput {\n  accountNumber: String!\n  accountName: String!\n  bankCode: String!\n}\n\ntype Query {\n  validatePayee(input: ValidatePayeeInput!): ValidatePayeeResult!\n  getPayee(id: ID!): Payee\n}\n\ntype Mutation {\n  _empty: String\n}\n";
